from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Return the maximum depth of nested parentheses for each group in the input string.
    Groups are separated by whitespace.
    """
    def max_depth_of_group(group: str) -> int:
        depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
        return max_depth

    return [max_depth_of_group(g) for g in paren_string.split() if g]
