from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Return the maximum depth of nested parentheses for each group in the input string.
    Groups are separated by whitespace. Raises ValueError if a group contains
    unmatched parentheses.
    """
    def parse_paren_group(s: str) -> int:
        depth = 0
        max_depth = 0
        for c in s:
            if c == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif c == ')':
                depth -= 1
                if depth < 0:
                    raise ValueError(f"Unmatched closing parenthesis in group '{s}'")
        if depth != 0:
            raise ValueError(f"Unmatched opening parenthesis in group '{s}'")
        return max_depth

    return [parse_paren_group(group) for group in paren_string.split() if group]
