def largest_divisor(n: int) -> int:
    """
    Return the largest integer that divides n evenly and is smaller than n.
    For n <= 1, 1 is returned as a safe default.
    """
    if n <= 1:
        return 1

    # The largest possible proper divisor is at most n // 2.
    for d in range(n // 2, 0, -1):
        if n % d == 0:
            return d

    # Fallback (should never be reached for n > 1)
    return 1

def largest_divisor(n: int) -> int:
    """
    Return the largest integer that divides n evenly and is strictly smaller than n.
    For n <= 1, the function returns 1 (the only divisor of 1).
    """
    if n <= 1:
        return 1

    # Any proper divisor of n must be <= n//2
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i

    # Fallback: n is prime, so the largest proper divisor is 1
    return 1

def flip_case(string: str) -> str:
    """
    Return a new string with all lowercase letters converted to uppercase
    and all uppercase letters converted to lowercase.
    """
    return string.swapcase()

