import math

def poly(xs: list, x: float) -> float:
    """Evaluate the polynomial with coefficients xs at point x."""
    return sum(coeff * (x ** i) for i, coeff in enumerate(xs))

def find_zero(xs: list) -> float:
    """
    Find a real root of the polynomial defined by the coefficient list xs.
    The list must contain an even number of coefficients and the leading
    non‑zero coefficient guarantees at least one real root.
    """
    # Initial interval
    begin, end = -1.0, 1.0

    # Expand the interval until a sign change occurs
    while poly(xs, begin) * poly(xs, end) > 0:
        begin *= 2.0
        end *= 2.0

    # If the root lies exactly at one of the endpoints, return it
    if poly(xs, begin) == 0:
        return begin
    if poly(xs, end) == 0:
        return end

    # Bisection method
    while end - begin > 1e-10:
        mid = (begin + end) / 2.0
        if poly(xs, mid) * poly(xs, begin) > 0:
            begin = mid
        else:
            end = mid

    # Return the midpoint of the final interval as the root approximation
    return (begin + end) / 2.0

