def decode_cyclic(s: str) -> str:
    """
    Reverse the transformation performed by `encode_cyclic`.

    The original `encode_cyclic` is assumed to shift each character
    forward by one position in a cyclic manner.  This function
    restores the original string by shifting each character back
    by one.  The shift is applied separately for lowercase letters,
    uppercase letters, digits, and the printable ASCII range
    (32–126).  Characters outside these ranges are left unchanged.
    """
    def shift_back(c: str) -> str:
        # Lowercase letters
        if 'a' <= c <= 'z':
            return chr((ord(c) - 97 - 1) % 26 + 97)
        # Uppercase letters
        if 'A' <= c <= 'Z':
            return chr((ord(c) - 65 - 1) % 26 + 65)
        # Digits
        if '0' <= c <= '9':
            return chr((ord(c) - 48 - 1) % 10 + 48)
        # Printable ASCII (32–126)
        code = ord(c)
        if 32 <= code <= 126:
            new_code = code - 1
            if new_code < 32:
                new_code = 126
            return chr(new_code)
        # Non‑printable or other characters remain unchanged
        return c

    return ''.join(shift_back(ch) for ch in s)
