def triples_sum_to_zero(l: list) -> bool:
    """
    Return True if there exist three distinct indices i, j, k in the list
    such that l[i] + l[j] + l[k] == 0, otherwise False.
    """
    n = len(l)
    if n < 3:
        return False

    # Sort the list to enable the two‑pointer technique.
    sorted_l = sorted(l)

    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            total = sorted_l[i] + sorted_l[left] + sorted_l[right]
            if total == 0:
                return True
            if total < 0:
                left += 1
            else:
                right -= 1

    return False
