def pairs_sum_to_zero(l):
    """
    Return True if there exist two distinct elements in the list that sum to zero.
    """
    seen = set()
    for x in l:
        # If x is zero, we need at least one other zero already seen
        if x == 0:
            if 0 in seen:
                return True
        else:
            if -x in seen:
                return True
        seen.add(x)
    return False
