def fib(n: int) -> int:
    """
    Return the n-th Fibonacci number (1-indexed, with fib(1)=1, fib(2)=1).
    Supports fib(0)=0 for convenience.
    """
    if n < 0:
        raise ValueError("n must be a non‑negative integer")
    if n == 0:
        return 0

    a, b = 0, 1  # a = fib(k-1), b = fib(k)
    for _ in range(1, n):
        a, b = b, a + b
    return b

