def is_multiply_prime(a: int) -> bool:
    """
    Return True if `a` can be expressed as the product of exactly three prime numbers
    (counted with multiplicity), otherwise False.
    """
    if a <= 1:
        return False

    # Helper to test primality
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Count prime factors with multiplicity
    count = 0
    temp = a
    for p in range(2, int(temp ** 0.5) + 1):
        if is_prime(p):
            while temp % p == 0:
                count += 1
                temp //= p
                if count > 3:  # early exit if more than 3 factors
                    return False
    if temp > 1:  # remaining factor is prime
        count += 1

    return count == 3
