def is_simple_power(x: int, n: int) -> bool:
    """
    Return True if x is a simple power of n (i.e. there exists an integer k such that n**k == x),
    otherwise return False.
    """
    # Handle trivial cases
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    if n == 0:
        return x == 0

    # 1 is always a power (n**0) for any n != 0
    if x == 1:
        return True
    # 0 can only be a power of 0
    if x == 0:
        return False

    # Positive n cannot produce a negative result
    if n > 0 and x < 0:
        return False

    power = 1
    while True:
        power *= n
        if power == x:
            return True
        # Stop when the magnitude of power exceeds that of x
        if (n > 0 and power > x) or (n < 0 and abs(power) > abs(x)):
            return False
