def numerical_letter_grade(grades):
    """
    Convert a list of numeric GPAs to their corresponding letter grades.

    Parameters
    ----------
    grades : list[float]
        A list of GPA values (0.0 to 4.0 inclusive).

    Returns
    -------
    list[str]
        A list of letter grades in the same order as the input.
