    """
    Return True if all keys in the dictionary are strings that are either
    all lower‑case or all upper‑case. Return False for an empty dictionary,
    for any non‑string key, or if the keys are mixed case or contain
    characters that are not strictly lower‑case or upper‑case letters.
    """
    if not d:
        return False

    state = None  # None, 'lower', or 'upper'

    for key in d:
        # Key must be a string
        if not isinstance(key, str):
            return False

        # Key must be strictly lower or upper case
        if key.islower():
            if state is None:
                state = 'lower'
            elif state == 'upper':
                return False
        elif key.isupper():
            if state is None:
                state = 'upper'
            elif state == 'lower':
                return False
        else:
            # Mixed case or contains non‑letter characters
            return False

    # All keys satisfied the condition
    return state in ('lower', 'upper')
