def _is_prime(num: int) -> bool:
    """Return True if num is a prime number, otherwise False."""
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    limit = int(math.isqrt(num))
    for divisor in range(3, limit + 1, 2):
        if num % divisor == 0:
            return False
    return True

def count_up_to(n: int) -> list[int]:
    """
    Return a list of all prime numbers less than n.

    Parameters
    ----------
    n : int
        Non‑negative integer upper bound (exclusive).

    Returns
    -------
    list[int]
        List of primes < n in ascending order.
    """
    if n <= 2:
        return []

    primes = []
    for candidate in range(2, n):
        if _is_prime(candidate):
            primes.append(candidate)
    return primes

