def even_odd_palindrome(n: int) -> tuple[int, int]:
    """
    Return a tuple (even_count, odd_count) where each element is the number of
    even and odd integer palindromes in the inclusive range [1, n].
    """
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
