def _ones_count(x: int) -> int:
    """
    Count the number of 1-bits in the binary representation of x.
    For non‑negative numbers the usual binary representation is used.
    For negative numbers a 32‑bit two's‑complement representation is assumed.
    """
    if x >= 0:
        return bin(x).count("1")
    # 32‑bit two's complement for negative numbers
    return bin(x & 0xFFFFFFFF).count("1")


