def fix_spaces(text: str) -> str:
    """
    Replace all spaces in `text` with underscores, except that any run of
    more than two consecutive spaces is replaced by a single hyphen.

    Examples:
        fix_spaces("Example")          -> "Example"
        fix_spaces("Example 1")        -> "Example_1"
        fix_spaces(" Example 2")       -> "_Example_2"
        fix_spaces(" Example   3")     -> "_Example-3"
    """
    result = []
    space_count = 0

    for ch in text:
        if ch == ' ':
            space_count += 1
        else:
            if space_count:
                if space_count > 2:
                    result.append('-')
                else:
                    result.append('_' * space_count)
                space_count = 0
            result.append(ch)

    # Handle trailing spaces, if any
    if space_count:
        if space_count > 2:
            result.append('-')
        else:
            result.append('_' * space_count)

    return ''.join(result)
