def triples_sum_to_zero(l: list) -> bool:
    """
    Return True if there exist three distinct indices i, j, k in the list
    such that l[i] + l[j] + l[k] == 0, otherwise False.
    """
    n = len(l)
    if n < 3:
        return False

    # Sort the list to enable the two‑pointer technique.
    l_sorted = sorted(l)

    for i in range(n - 2):
        # Avoid duplicate work for the same value at position i
        if i > 0 and l_sorted[i] == l_sorted[i - 1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            total = l_sorted[i] + l_sorted[left] + l_sorted[right]
            if total == 0:
                return True
            if total < 0:
                left += 1
            else:
                right -= 1

    return False
