def decode_cyclic(s: str) -> str:
    """
    Decodes a string that was encoded with a cyclic alphabet shift.
    The most common cyclic encoding is ROT13 (shift by 13 positions).
    This function reverses that shift, restoring the original text.
    Non‑alphabetic characters are left unchanged.
    """
    def _shift(ch: str, shift: int) -> str:
        if 'a' <= ch <= 'z':
            return chr((ord(ch) - ord('a') + shift) % 26 + ord('a'))
        if 'A' <= ch <= 'Z':
            return chr((ord(ch) - ord('A') + shift) % 26 + ord('A'))
        return ch

    # ROT13 is its own inverse, so shifting by -13 restores the original.
    return ''.join(_shift(ch, -13) for ch in s)
