def decode_shift(s: str) -> str:
    """
    Reverse a simple shift cipher that moves each alphabetic character forward by one
    position (with wrap‑around). Non‑alphabetic characters are left unchanged.

    Example:
        encode_shift('bcd') -> 'cde'
        decode_shift('cde') -> 'bcd'
