        if 'a' <= ch <= 'z':
            return chr(ord('z') if ch == 'a' else ord(ch) - 1)
        # Handle uppercase letters
        if 'A' <= ch <= 'Z':
            return chr(ord('Z') if ch == 'A' else ord(ch) - 1)
        # Non‑alphabetic characters are unchanged
        return ch

    return ''.join(_shift_back(ch) for ch in s)
