def iscube(a: int) -> bool:
    """
    Return True if the integer `a` is a perfect cube of some integer.
    Handles negative numbers and zero.
    """
    if a == 0:
        return True

    n = abs(a)
    low, high = 0, n
    while low <= high:
        mid = (low + high) // 2
        cube = mid * mid * mid
        if cube == n:
            return True
        if cube < n:
            low = mid + 1
        else:
            high = mid - 1
    return False

def is_happy(s: str) -> bool:
    """
    Return True if the string is "happy":
    - length is at least 3
    - every 3 consecutive characters are all distinct
    """
    if len(s) < 3:
        return False

    # Check each window of length 3
    for i in range(len(s) - 2):
        if len({s[i], s[i + 1], s[i + 2]}) != 3:
            return False
    return True

def is_happy(s: str) -> bool:
    """
    Return True if the string `s` is happy, otherwise False.
    A string is happy if its length is at least 3 and every
    consecutive group of three characters contains three distinct
    letters.
    """
    if len(s) < 3:
        return False

    for i in range(len(s) - 2):
        if len(set(s[i:i+3])) != 3:
            return False
    return True

