def anti_shuffle(s: str) -> str:
    """
    Return a string where each word (sequence of non‑space characters) is
    replaced by its characters sorted in ascending ASCII order.
    The original order of words and the exact spacing are preserved.
    """
    def sort_word(word: str) -> str:
        """Return the characters of *word* sorted by ASCII value."""
        return ''.join(sorted(word))

    result = []
    word_buf = []

    for ch in s:
        if ch == ' ':
            # Flush the current word (if any) before adding the space
            if word_buf:
                result.append(sort_word(''.join(word_buf)))
                word_buf = []
            result.append(' ')  # preserve the space
        else:
            word_buf.append(ch)

    # Flush the last word if the string does not end with a space
    if word_buf:
        result.append(sort_word(''.join(word_buf)))

    return ''.join(result)
