def encrypt(s: str) -> str:
    """
    Encrypts the input string by shifting each alphabetic character
    forward by 4 positions (Caesar cipher with a shift of 4).
    Non‑alphabetic characters are left unchanged.
    """
    def shift_char(ch: str, shift: int = 4) -> str:
        if 'a' <= ch <= 'z':
            base = ord('a')
            return chr((ord(ch) - base + shift) % 26 + base)
        if 'A' <= ch <= 'Z':
            base = ord('A')
            return chr((ord(ch) - base + shift) % 26 + base)
        return ch

    return ''.join(shift_char(c) for c in s)
