def next_smallest(lst):
    """
    Return the second smallest distinct element in `lst`.
    If there is no such element, return None.
    """
    min1 = None  # smallest
    min2 = None  # second smallest

    for x in lst:
        # Skip duplicates of the current smallest
        if min1 is not None and x == min1:
            continue

        if min1 is None or x < min1:
            # New smallest found; previous smallest becomes second smallest
            if min1 is not None:
                min2 = min1
            min1 = x
        elif min2 is None or x < min2:
            # New candidate for second smallest
            min2 = x

    return min2

def _is_int(value: object) -> bool:
    """
    Return True if value is an integer (excluding booleans).
    """
    return isinstance(value, int) and not isinstance(value, bool)


def any_int(x: object, y: object, z: object) -> bool:
    """
    Return True if all three arguments are integers and one of them equals
    the sum of the other two. Otherwise return False.
    """
    if not (_is_int(x) and _is_int(y) and _is_int(z)):
        return False

    return x == y + z or y == x + z or z == x + y

def encode(message: str) -> str:
    """
    Encode a message by swapping the case of all letters and replacing
    each vowel with the letter that appears two places ahead in the
    alphabet. Non‑letter characters are left unchanged.
    """
    # Mapping of vowels to the letter two positions ahead
    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    result = []

    for ch in message:
        if ch.isalpha():
            # Swap case
            swapped = ch.swapcase()
            # Replace vowel if needed
            replaced = vowel_map.get(swapped, swapped)
            result.append(replaced)
        else:
            # Preserve non‑letters (e.g., spaces, punctuation)
            result.append(ch)

    return ''.join(result)

