    """
    Return True if all keys in the dictionary are strings that are either
    all lower‑case or all upper‑case. Return False if the dictionary is
    empty, contains a non‑string key, or the keys are mixed case.
    """
    if not d:
        return False

    # Ensure every key is a string
    for key in d:
        if not isinstance(key, str):
            return False

    # Determine the expected case from the first key
    first_key = next(iter(d))
    if first_key.islower():
        expected = "lower"
    elif first_key.isupper():
        expected = "upper"
    else:
