    first_key = next(iter(d))
    if first_key.islower():
        expected = "lower"
    elif first_key.isupper():
        expected = "upper"
    else:
        # key is not strictly lower or upper (e.g., contains digits or symbols)
        return False

    # Verify all keys match the expected case
    for key in d:
        if expected == "lower" and not key.islower():
            return False
        if expected == "upper" and not key.isupper():
            return False

    return True

