def sort_array(arr):
    """
    Sort an array of integers by the number of 1-bits in their binary representation.
    For numbers with the same bit count, sort by their decimal value.
    Negative numbers are sorted by their decimal value after all non‑negative numbers.
    """
    def _key(x):
        if x >= 0:
            # Count the number of '1' bits in the binary representation of a non‑negative integer.
            return (bin(x).count('1'), x)
        # Use a very large key for negative numbers so they come after non‑negative ones.
        return (float('inf'), x)

    return sorted(arr, key=_key)
