def sort_array(arr):
    """
    Sort an array of integers by the number of 1s in their binary representation
    (ascending). For numbers with the same count of 1s, sort by their decimal
    value (ascending). Negative numbers are sorted only by their decimal value.
    """
    def _key(n: int):
        # For non‑negative numbers: (ones count, value)
        # For negative numbers: (0, value) – they are sorted only by value
        if n < 0:
            return (0, n)
        # Use bit_count() if available for speed, otherwise fall back to bin()
        ones = n.bit_count() if hasattr(n, "bit_count") else bin(n).count("1")
        return (ones, n)

    return sorted(arr, key=_key)
