def get_closest_vowel(word: str) -> str:
    """
    Return the closest vowel that is surrounded by consonants,
    searching from the right side of the word.  Vowels at the
    beginning or end of the word are ignored.  If no such vowel
    exists, return an empty string.
    """
    if len(word) < 3:
        return ""

    vowels = set("aeiouAEIOU")

    # Scan from right to left, skipping the first and last character
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            if word[i - 1] not in vowels and word[i + 1] not in vowels:
                return word[i]
    return ""

def get_odd_collatz(n: int) -> list[int]:
    """
    Return a sorted list of the odd numbers that appear in the Collatz sequence
    starting from the positive integer `n` and ending at 1.

    Parameters
    ----------
    n : int
        The starting positive integer of the Collatz sequence.

    Returns
    -------
    list[int]
        Sorted list (ascending) of all odd numbers encountered in the sequence.
    """
    if n <= 0 or not isinstance(n, int):
        raise ValueError("n must be a positive integer")

    odds = []

    while True:
        if n % 2 == 1:
            odds.append(n)

        if n == 1:
            break

        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1

    return sorted(odds)

