    """
    Split a string into words based on the following rules:
    1. If the string contains any whitespace, split on whitespace.
    2. Else if the string contains any commas, split on commas.
    3. Else return the count of lower‑case letters with odd alphabetical index
       (a=0, b=1, ..., z=25).
    """
    # Rule 1: whitespace split
    if txt.strip() != txt:  # there is at least one whitespace character
        return txt.split()

    # Rule 2: comma split
    if ',' in txt:
        return txt.split(',')

    # Rule 3: count odd‑indexed lower‑case letters
    return sum(1 for ch in txt if 'a' <= ch <= 'z' and ((ord(ch) - ord('a')) % 2 == 1))

