def is_sorted(lst: List[int]) -> bool:
    """
    Return True if `lst` is sorted in ascending order and no number appears
    more than twice. Empty lists and single‑element lists are considered sorted.
    """
    if not lst:
        return True

    counts = {lst[0]: 1}
    prev = lst[0]

    for num in lst[1:]:
        # Check ascending order
        if num < prev:
            return False

        # Count occurrences and enforce at most two
        counts[num] = counts.get(num, 0) + 1
        if counts[num] > 2:
            return False

        prev = num

    return True

