def minPath(grid, k):
    """
    Return the lexicographically minimal path of length k in the given grid.
    The grid is an N x N list of lists containing a permutation of 1..N*N.
    A path of length k visits exactly k cells, moving each step to an
    orthogonally adjacent cell (no staying in place).
    """
    n = len(grid)
    # locate the cell containing the value 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
                break
        else:
            continue
        break

    # find the minimal neighbor value of the cell containing 1
    min_neighbor = None
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            val = grid[nr][nc]
            if min_neighbor is None or val < min_neighbor:
                min_neighbor = val

    # Build the alternating sequence [1, min_neighbor, 1, min_neighbor, ...]
    result = []
    for idx in range(k):
        if idx % 2 == 0:
            result.append(1)
        else:
            result.append(min_neighbor)
    return result
