def minPath(grid, k):
    """
    Return the lexicographically minimal path of length k in the given grid.
    The path is represented as a list of the values of the visited cells.
    """
    N = len(grid)
    # Map each value to its coordinates
    pos = {}
    for i in range(N):
        for j in range(N):
            pos[grid[i][j]] = (i, j)

    # Starting position is the cell containing the value 1
    start = pos[1]
    if k == 1:
        return [1]

    # Precompute the 4-neighbor list for every cell
    neighbors = [[[] for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N:
                    neighbors[i][j].append((ni, nj))

    # reachable[l][i][j] == True  <=>  there exists a path of length l
    # starting from cell (i, j) (including that cell)
    reachable = [[[False] * N for _ in range(N)] for _ in range(k + 1)]
    for i in range(N):
        for j in range(N):
            reachable[1][i][j] = True

    for l in range(2, k + 1):
        for i in range(N):
            for j in range(N):
                for ni, nj in neighbors[i][j]:
                    if reachable[l - 1][ni][nj]:
                        reachable[l][i][j] = True
                        break

    # Build the lexicographically minimal path
    path = [1]
    cur = start
    for step in range(1, k):          # step counts how many cells are already in the path
        remaining = k - step          # number of cells that still need to be visited
        best_val = None
        best_pos = None
        for ni, nj in neighbors[cur[0]][cur[1]]:
            if reachable[remaining][ni][nj]:
                val = grid[ni][nj]
                if best_val is None or val < best_val:
                    best_val = val
                    best_pos = (ni, nj)
        # According to the problem statement, a solution always exists
        path.append(best_val)
        cur = best_pos

    return path
