import math
from typing import Any, Union

Number = Union[int, float, str]


def _to_float(value: Number) -> float:
    """
    Convert an int, float or numeric string (with '.' or ',') to a float.
    Raises ValueError if the string cannot be parsed.
    """
    if isinstance(value, str):
        s = value.strip().replace(",", ".")
        try:
            return float(s)
        except ValueError as exc:
            raise ValueError(f"Cannot parse numeric string: {value}") from exc
    if isinstance(value, (int, float)):
        return float(value)
    raise TypeError(f"Unsupported type: {type(value).__name__}")


def compare_one(a: Number, b: Number) -> Any:
    """
    Return the larger of a and b in its original type.
    If the numeric values are equal (within floating‑point tolerance), return None.
    """
    a_val = _to_float(a)
    b_val = _to_float(b)

    # Use isclose to handle floating‑point equality
    if math.isclose(a_val, b_val, rel_tol=1e-9, abs_tol=0.0):
        return None

    return a if a_val > b_val else b
