def cycpattern_check(a: str, b: str) -> bool:
    """
    Return True if any rotation of string `b` is a substring of string `a`.
    """
    # An empty pattern is trivially found in any string
    if not b:
        return True

    # If the pattern is longer than the text, it can never match
    if len(b) > len(a):
        return False

    # Check each cyclic rotation of `b`
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True

    return False

