def even_odd_count(num: int) -> tuple[int, int]:
    """
    Return a tuple (even_count, odd_count) of the digits in the given integer.
    Negative signs are ignored.
    """
    n = abs(num)

    # Special case: 0 has one even digit
    if n == 0:
        return (1, 0)

    even = odd = 0
    while n:
        digit = n % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        n //= 10

    return (even, odd)
