def find_max(words):
    """
    Return the word with the maximum number of unique characters.
    If several words tie, return the lexicographically smallest one.
    If the input list is empty, return an empty string.
    """
    if not words:
        return ""

    # Helper to count unique characters in a word
    def unique_count(word: str) -> int:
        return len(set(word))

    # Find the best word using a single pass
    best_word = words[0]
    best_unique = unique_count(best_word)

    for word in words[1:]:
        u = unique_count(word)
        if u > best_unique or (u == best_unique and word < best_word):
            best_word = word
            best_unique = u

    return best_word

