def solve(s: str) -> str:
    """
    Return a new string where each alphabetic character has its case reversed.
    Non‑alphabetic characters are left unchanged.
    If the input string contains no alphabetic characters, return the string reversed.
    """
    has_letter = any(ch.isalpha() for ch in s)
    if not has_letter:
        return s[::-1]

    # Build the transformed string
    result = []
    for ch in s:
        if ch.islower():
            result.append(ch.upper())
        elif ch.isupper():
            result.append(ch.lower())
        else:
            result.append(ch)
    return "".join(result)
