import hashlib

def string_to_md5(text: str) -> str | None:
    """
    Return the MD5 hash of the given string as a hexadecimal string.
    If the input string is empty, return None.
    """
    if text == "":
        return None
    # Encode the string to bytes (UTF‑8) before hashing
    return hashlib.md5(text.encode("utf-8")).hexdigest()
